              "type": "object",
              "properties": {
                "nodeId": {
                  "type": "number",
                  "description": "节点 ID"
                },
                "parentNodeId": {
                  "type": [
                    "number",
                    "null"
                  ],
                  "description": "父节点 ID，可能为 null"
                },
                "level": {
                  "type": "number",
                  "description": "节点层级"
                },
                "desc": {
                  "type": "string",
                  "description": "节点描述/名称"
                },
                "target": {
                  "type": "string",
                  "description": "跳转目标类型，例如 GROUP"
                },
                "outBizKey": {
                  "type": [
                    "string",
                    "null"
